function buscaBinaria(lista, alvo) {
  let low = 0;
  let high = lista.length - 1;
  
  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    const chute = lista[mid];
    
    if (chute === alvo) {
      return mid; // Retorna índice encontrado
    } else if (chute > alvo) {
      high = mid - 1;
    } else {
      low = mid + 1;
    }
  }
  return -1; // Não encontrado
}

